# Check the expansion predicates printed in Algorithms 1 and 2.
subjects={'s1','s2'}
items={'x1','x2'}
edges={(s,x) for s in subjects for x in items}
train={('s1','x1')}
test={('s2','x2')}
train_subjects={s for s,x in train}
test_subjects={s for s,x in test}
train_items={x for s,x in train}
test_items={x for s,x in test}
eeg_train=train|{(s,x) for s,x in edges if s not in test_subjects}
eeg_test=test|{(s,x) for s,x in edges if s not in train_subjects}
fmri_train=train|{(s,x) for s,x in edges if x not in test_items}
fmri_test=test|{(s,x) for s,x in edges if x not in train_items}
print('Algorithm 1 expansion yields shared texts:',sorted({x for s,x in eeg_train}&{x for s,x in eeg_test}))
print('Algorithm 2 expansion yields shared subjects:',sorted({s for s,x in fmri_train}&{s for s,x in fmri_test}))
# A dataset with disconnected subject-stimulus components admits a lossless split.
disconnected={('s1','x1'),('s2','x2')}
print('Lossless disjoint split counterexample:',train|test==disconnected and not(train_subjects&test_subjects) and not(train_items&test_items))
